class NarrowRiverScaleTest{public static void main(String[]a){int n=128,size=1024;var h=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)h[z*n+x]=180-z*.7f+Math.abs(x-64)*.1f;var e=new EnvironmentMap(h);e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVERS,0,0);node.values.put("width",7.0);node.values.put("courses",0.0);node.values.put("avoidDips",0.0);node.values.put("sources",1.0);node.values.put("widthVariation",.2);var result=EnvironmentNodes.apply(node,e,null,n,size,62,2024,()->false);if(result.ribbons==null)throw new AssertionError("No river");double avg=result.ribbons.segments.stream().mapToDouble(s->s.a().radius()*2).average().orElseThrow();double max=result.ribbons.segments.stream().mapToDouble(s->s.a().radius()*2).max().orElseThrow();if(avg<6||avg>8.5||max>10)throw new AssertionError("Coarse-grid inflated width: avg="+avg+" max="+max);System.out.println("PASS: 7-block rivers retain physical width on 8-block coarse grid; mean="+avg+" max="+max);}}
